# -*- coding: utf-8 -*-

from __future__ import with_statement
from os.path import exists
from os.path import join


CONF_VERSION = 1

########################################################################
class ConfigParser:

    #----------------------------------------------------------------------
    def __init__(self, configdir):
        """Constructor"""
        self.configdir = configdir
        self.config = {}

        if self.checkVersion():
            self.readConfig()

    #----------------------------------------------------------------------
    def checkVersion(self):

        if not exists(join(self.configdir, "pyload.conf")):
            return False
        f = open(join(self.configdir, "pyload.conf"), "rb")
        v = f.readline()
        f.close()
        v = v[v.find(":")+1:].strip()

        if int(v) < CONF_VERSION:
            return False

        return True    

    #----------------------------------------------------------------------
    def readConfig(self):
        """reads the config file"""

        self.config = self.parseConfig(join(self.configdir, "pyload.conf"))


    #----------------------------------------------------------------------
    def parseConfig(self, config):
        """parses a given configfile"""

        f = open(config)

        config = f.read()

        config = config.split("\n")[1:]

        conf = {}

        section, option, value, typ, desc = "","","","",""

        listmode = False

        for line in config:

            line = line.rpartition("#") # removes comments

            if line[1]:
                line = line[0]
            else:
                line = line[2]

            line = line.strip()            

            try:

                if line == "":
                    continue
                elif line.endswith(":"):
                    section, none, desc = line[:-1].partition('-')
                    section = section.strip()
                    desc = desc.replace('"', "").strip()
                    conf[section] = { "desc" : desc }
                else:
                    if listmode:

                        if line.endswith("]"):
                            listmode = False
                            line = line.replace("]","")

                        value += [self.cast(typ, x.strip()) for x in line.split(",") if x]

                        if not listmode:
                            conf[section][option] = { "desc" : desc,
                                                      "type" : typ,
                                                      "value" : value} 


                    else:
                        content, none, value = line.partition("=")

                        content, none, desc = content.partition(":")

                        desc = desc.replace('"', "").strip()

                        typ, option = content.split()

                        value = value.strip()

                        if value.startswith("["):
                            if value.endswith("]"):                            
                                listmode = False
                                value = value[:-1]
                            else:
                                listmode = True

                            value = [self.cast(typ, x.strip()) for x in value[1:].split(",") if x]
                        else:
                            value = self.cast(typ, value)

                        if not listmode:
                            conf[section][option] = { "desc" : desc,
                                                      "type" : typ,
                                                      "value" : value}

            except:
                pass


        f.close()
        return conf

    #----------------------------------------------------------------------
    def cast(self, typ, value):
        """cast value to given format"""
        if type(value) not in (str, unicode):
            return value

        if typ == "int":
            return int(value)
        elif typ == "bool":
            return True if value.lower() in ("1","true", "on", "an","yes") else False
        else:
            return value

    #----------------------------------------------------------------------
    def get(self, section, option):
        """get value"""
        return self.config[section][option]["value"]

    #----------------------------------------------------------------------
    def __getitem__(self, section):
        """provides dictonary like access: c['section']['option']"""
        return Section(self, section)

########################################################################
class Section:
    """provides dictionary like access for configparser"""

    #----------------------------------------------------------------------
    def __init__(self, parser, section):
        """Constructor"""
        self.parser = parser
        self.section = section

    #----------------------------------------------------------------------
    def __getitem__(self, item):
        """getitem"""
        return self.parser.get(self.section, item)

from __future__ import absolute_import

import logging
from uuid import uuid1

import dockets.queue
import dockets.error_queue

from .base import Queue

class DocketsQueue(Queue):
    def __init__(self, redis_client, queue_name, wait_time, timeout):
        self.queue = dockets.queue.Queue(redis_client,
                                         queue_name,
                                         use_error_queue=True,
                                         wait_time=wait_time,
                                         timeout=timeout)

    def make_error_queue(self):
        return DocketsErrorQueue(self.queue)

    def _push(self, item):
        push_kwargs = {}
        if 'delay' in item:
            push_kwargs['delay'] = item['delay'] or None
        return self.queue.push(item, **push_kwargs)

    def _push_batch(self, items):
        result = []
        for item in items:
            try:
                self._push(item)
                result.append((item, True))
            except Exception:
                logging.exception("Error pushing item {}".format(item))
                result.append((item, False))
        return result

    def _pop(self):
        envelope = self.queue.pop()
        if envelope:
            return envelope, envelope.get('item')
        return None, None

    def _pop_batch(self, batch_size):
        batch = []
        for _ in range(batch_size):
            envelope, item = self._pop()
            if envelope:
                batch.append((envelope, item))
            else:
                break
        return batch

    def _touch(self, envelope, seconds):
        """Dockets heartbeat is consumer-level and does not
        utilize the envelope or seconds arguments."""
        return self.queue._heartbeat()

    def _complete(self, envelope):
        return self.queue.complete(envelope)

    def _complete_batch(self, envelopes):
        # Dockets doesn't return any information from complete, so here we go...
        for envelope in envelopes:
            self._complete(envelope)
        return [(envelope, True) for envelope in envelopes]

    def _flush(self):
        while True:
            envelope, item = self._pop()
            if envelope is None:
                break
            self._complete(envelope)

    def _stats(self):
        return {'available': self.queue.queued(),
                'in_flight': self.queue.working(),
                'delayed': self.queue.delayed()}

class DocketsErrorQueue(Queue):
    FIFO = False
    SUPPORTS_DELAY = False
    RECLAIMS_TO_BACK_OF_QUEUE = False

    def __init__(self, parent_dockets_queue):
        self.queue = dockets.error_queue.ErrorQueue(parent_dockets_queue)

    def _push(self, item):
        """This error ID dance is Dockets-specific, since we need the ID
        to interface with the hash error queue. Other backends shouldn't
        need to do this and should use the envelope properly instead."""
        try:
            error_id = item['error']['id']
        except KeyError:
            logging.warn('No error ID found for item, will generate and add one: {}'.format(item))
            error_id = str(uuid1())
            item.setdefault('error', {})['id'] = error_id
        return self.queue.queue_error_item(error_id, item)

    def _push_batch(self, items):
        result = []
        for item in items:
            try:
                self._push(item)
                result.append((item, True))
            except Exception:
                logging.exception("Error pushing item {}".format(item))
                result.append((item, False))
        return result

    def _pop(self):
        """Dockets Error Queues are not actually queues, they're hashes. There's no way
        for us to implement a pure pop that doesn't expose us to the risk of dropping
        data. As such, we're going to return the first error in that hash but not actually
        remove it until we call `_complete` later on. This keeps our data safe but may
        deliver errors multiple times. That should be okay."""
        error_ids = self.queue.error_ids()
        if error_ids:
            error_id = error_ids[0]
            error = self.queue.error(error_id)
            return error, error
        return None, None

    def _pop_batch(self, batch_size):
        """Similar to _pop, but returns a list of tuples containing batch_size pops
        from our queue.
        Again, this does not actually pop from the queue until we call _complete on
        each queued item"""
        error_ids = self.queue.error_ids()
        batch = []
        if error_ids:
            for error_id in error_ids[:batch_size]:
                error = self.queue.error(error_id)
                batch.append((error, error))
        return batch

    def _touch(self, envelope, seconds):
        return None

    def _complete(self, envelope):
        error_id = envelope['error']['id']
        if not error_id:
            raise AttributeError('Error item has no id field: {}'.format(envelope))
        return self.queue.delete_error(error_id)

    def _complete_batch(self, envelopes):
        return [(envelope, bool(self._complete(envelope))) for envelope in envelopes]

    def _flush(self):
        for error_id in self.queue.error_ids():
            self.queue.delete_error(error_id)

    def _stats(self):
        return {'available': self.queue.length()}

#coding: utf-8
from scapy.all import *

class WILDCARD:
    """ Used to indicate that some fields in a scapy packet should be ignored when comparing """
    pass

class NO_PKT:
    """ Indicate that a sent packet should have no reply """
    pass

def pkt_match(expected, actual):
    """ Check if all fields described in packet `expected` match the fields of pkt `actual`' """

    if expected == NO_PKT and actual == NO_PKT:
        return True
    elif expected == NO_PKT or actual == NO_PKT:
        return False

    if expected.oif != WILDCARD and expected.oif != actual.oif:
        # This can't be added to `fields` because it's not a proper scapy field
        return False

    fields = {
        IPv6: ('src', 'dst'),
        IPv6ExtHdrSegmentRouting: ('addresses', 'lastentry', 'segleft', 'tag',
            'unused1', 'protected', 'oam', 'alert', 'hmac', 'unused2'), # Flags
        IPv6ExtHdrSegmentRoutingTLVHMAC : ('hmac', 'keyid'),
        IPv6ExtHdrSegmentRoutingTLVIngressNode : ('ingress_node',),
        IPv6ExtHdrSegmentRoutingTLVEgressNode : ('egress_node',),
        IPv6ExtHdrSegmentRoutingTLVOpaque : ('container',),
        IPv6ExtHdrSegmentRoutingTLVPadding : ('len',),
        IPv6ExtHdrSegmentRoutingTLVNSHCarrier : ('nsh_object',),
        IPv6ExtHdrSegmentRoutingTLV : ('type', 'value'),
        TCP: ('sport', 'dport'),
        UDP: ('sport', 'dport'),
        Raw: ('load',)
    }

    layer = 0
    while 1:
        sub_expected, sub_actual = expected.getlayer(layer), actual.getlayer(layer)

        if sub_expected.__class__ != sub_actual.__class__:
            return False

        if sub_actual == None: # Compared all layers
            return True

        if sub_actual.__class__ not in fields: # Unknown layer ..
            return False

        for field in fields[sub_expected.__class__]:
            # Don't care if field not set in expected packet
            if getattr(sub_expected, field) != WILDCARD and \
                getattr(sub_expected, field) != getattr(sub_actual, field):
                    return False

        layer += 1

def pkt_str(pkt):
    if pkt == NO_PKT:
        return "none"

    _ = lambda x: x if x != WILDCARD else "*"

    def srh_str(srh):
        from collections import OrderedDict

        segs = list(srh.addresses)
        if srh.segleft and srh.segleft < len(segs):
            segs[srh.segleft] = "+"+segs[srh.segleft]

        options = OrderedDict((('sl',srh.segleft), ('le',srh.lastentry)))

        if srh.tag:
            options['tag'] = srh.tag
        flags = ""
        fl_mapping = {'oam':'O', 'hmac':'H', 'alert':'A','protected':'P'} # TODO organiser selon draft
        for key,val in fl_mapping.items():
            if getattr(srh,key) == 1:
                flags += val

        if flags != "":
            options['fl'] = flags

        tlvs = []
        for tlv in srh.tlv_objects:
            if isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVHMAC):
                tlvs.append('{{HMAC: {}, {}}}'.format(tlv.hmac.encode('hex'), tlv.keyid))
            elif isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVPadding):
                tlvs.append('{{Pad: {}}}'.format(tlv.len))
            elif isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVIngressNode):
                tlvs.append('{{Ingr: {}}}'.format(tlv.ingress_node))
            elif isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVEgressNode):
                tlvs.append('{{Egr: {}}}'.format(tlv.egress_node))
            elif isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVOpaque):
                tlvs.append('{{Opaq: {}}}'.format(tlv.container.encode('hex')))
            elif isinstance(tlv,IPv6ExtHdrSegmentRoutingTLVNSHCarrier):
                tlvs.append('{{NSH: {}}}'.format(tlv.nsh_object.encode('hex')))
            else:
                tlvs.append('{{Type:{} Value:{}}}'.format(tlv.type, tlv.value.encode('hex')))


        return "[{}] <{}>{}".format(",".join(segs), ",".join(map(lambda key: "{} {}".format(key, options[key]),options)), "" if not tlvs else " "+" ".join(tlvs))

    def ip_str(ip):
        return  "{} -> {}".format(_(ip.src), _(ip.dst))

    def udp_str(udp):
        if udp.sport or udp.dport:
            return "UDP({},{})".format(_(udp.sport), _(udp.dport))
        return "UDP"

    def tcp_str(tcp):
        if tcp.sport or tcp.dport:
            return "TCP({},{})".format(_(tcp.sport), _(tcp.dport))
        return "TCP"

    def payload_str(raw):
        if raw.load == WILDCARD:
            return "*"
        return '"{}"'.format(raw.load)


    fcts = {
        IPv6: ip_str,
        IPv6ExtHdrSegmentRouting: srh_str,
        UDP: udp_str,
        TCP: tcp_str,
        Raw: payload_str
    }

    i = 0
    protos = []
    while 1:
        layer = pkt.getlayer(i)
        if layer == None:
            break
        elif isinstance(layer, IPv6ExtHdrSegmentRoutingTLV):
            pass
        elif layer.__class__ in fcts:
            protos.append(fcts[layer.__class__](layer))
        else:
            protos.append(layer.name)

        i += 1

    iface = ""
    if pkt.oif and pkt.oif != "dum0" and pkt.oif != WILDCARD:
        iface = "({}) ".format(pkt.oif)
    return iface+" / ".join(protos)

class Event:
    type = None

    cmd = None #only used if CMD

    pkt = None # only used if PKT
    answer = None
    expected_answer = None

    oif = None # only used if OIF

    PKT = 1
    CMD = 2
    OIF = 3

    def __unicode__(self):
        return self.__str__()

    def __str__(self):
        if self.type == Event.PKT:
            s = "> {}".format(self.pkt)
            if self.expected_answer:
                s += "\n< {}".format(self.expected_answer)
            return s
        elif self.type == Event.CMD:
            return "`"+self.cmd+"`"
        elif self.type == Event.OIF:
            return "if add {}".format(self.oif)
        else:
            return "Unknown event"

    def __repr__(self):
        return self.__str__()

